using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "InvokeSpecificDieCustomBattleActionDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Any/InvokeSpecificDieCustomBattleActionDescription", order = 0)]
public class InvokeSpecificDieCustomBattleActionDescription : CustomBattleActionDescription
{
	private const string invokeSpecificDieID = "InvokeSpecificDie";

	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		InvokeAction invokeAction = battleAction as InvokeAction;
		string text = base.localizationManager.GetLocalizedString("InvokeSpecificDie");
		if (invokeAction.DestroyDieAfterInvoking || invokeAction.InvokedDieWontStayOnDrawPoolForTheRestOfTheBattle)
		{
			text = text.Split('\n').First();
		}
		string text2 = "";
		if (invokeAction.EnableExtraAction)
		{
			text2 = invokeAction.ExtraBattleAction.GetActionDescription(invokeAction.ExtraActionValue) + "\n";
		}
		return text2 + Smart.Format(text, invokeAction.SpecificDiceTag.GetTagName(), (GetAmountWithoutEquation(amountModified) == -2) ? 1 : GetAmountWithoutEquation(amountModified)) + (invokeAction.DestroyDieAfterInvoking ? ("\n" + base.localizationManager.GetLocalizedString("Purge_D")) : "");
	}
}
